const course = 'TypeScript';
const lessons = 6;
const label: string = `${course}: ${lessons} lessons`;
console.log(label);

function formatId(id: string | number): string {
  return typeof id === 'number' ? id.toFixed(0) : id.trim();
}
console.log(formatId(42));
console.log(formatId(' CT-7 '));

interface Skill {
  readonly id: string;
  name: string;
  level?: 'beginner' | 'intermediate';
}
const skill: Skill = { id: 's1', name: 'TypeScript' };
console.log(skill.name);

function average(values: readonly number[]): number {
  if (values.length === 0) throw new Error('values required');
  return values.reduce((sum, value) => sum + value, 0) / values.length;
}
console.log(average([70, 82, 91]));

function findById<T extends { id: string }>(items: readonly T[], id: string): T | undefined {
  return items.find(item => item.id === id);
}
const result = findById([{ id: 'a', score: 90 }], 'a');
console.log(result?.score);

type Progress = { topic: string; percent: number };
function isProgress(value: unknown): value is Progress {
  if (typeof value !== 'object' || value === null) return false;
  const item = value as Record<string, unknown>;
  return typeof item.topic === 'string' && typeof item.percent === 'number' && item.percent >= 0 && item.percent <= 100;
}
console.log(isProgress({ topic: 'Types', percent: 80 }));
